import{R as e,e as o,f as a,U as n}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Telegram","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/messaging/telegram.md","filePath":"integrations/messaging/telegram.md","lastUpdated":1775908585000}'),r={name:"integrations/messaging/telegram.md"};function i(l,t,s,g,h,c){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h1><p>Follow the below steps to connect to the Telegram API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Messaging</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Telegram</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-create-a-telegram-bot" tabindex="-1">Step 2. Create a Telegram Bot <a class="header-anchor" href="#step-2-create-a-telegram-bot" aria-label="Permalink to &quot;Step 2. Create a Telegram Bot&quot;">​</a></h3><ol><li>Open Telegram and search for <strong>@BotFather</strong>.</li><li>Start a chat and send the command <code>/newbot</code>.</li><li>Follow the prompts to give your bot a name and username.</li><li>Copy the <strong>Bot Token</strong> provided after creation.</li><li>Paste this value into the <strong>Bot Token</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar to verify the connection.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h3 id="step-5-get-your-chat-id" tabindex="-1">Step 5. Get Your Chat ID <a class="header-anchor" href="#step-5-get-your-chat-id" aria-label="Permalink to &quot;Step 5. Get Your Chat ID&quot;">​</a></h3><ol><li>Start a conversation with your bot, or add it to a group or channel.</li><li>Send a message in the chat where you&#39;d like the bot to post (this triggers a &quot;message update&quot;).</li><li>Visit the following URL in your browser (replace the token): <code>https://api.telegram.org/bot&lt;YOUR_BOT_TOKEN&gt;/getUpdates</code></li><li>Look for a <code>chat</code> object in the response. It will look something like: <code>&quot;chat&quot;: { &quot;id&quot;: -1001234567890, &quot;type&quot;: &quot;channel&quot;, &quot;title&quot;: &quot;Announcements&quot; }</code></li><li>Copy the <code>id</code> value and paste it into the <strong>Chat ID</strong> field when setting up the form integration.</li></ol><blockquote><p>💡 You can use a chat ID from a user, group, or channel — Telegram will route the message based on the ID automatically.</p></blockquote>',13)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
